<script type="application/ld+json">{"@context": "https://schema.org", "@type": "FAQPage", "inLanguage": "en", "mainEntity": [{"@type": "Question", "name": "Is KVKK mandatory for a small business’s website?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. KVKK applies to all individuals and legal entities that process personal data. Small businesses may be exempt from VERBİS registration, but the obligations to inform, keep data secure and respond to data subject requests still apply."}}, {"@type": "Question", "name": "Do I need explicit consent for a contact form?", "acceptedAnswer": {"@type": "Answer", "text": "Usually not. Processing data to respond to a request is generally considered preparation for entering into a contract or a legitimate interest; a privacy notice is enough. For marketing communications, however, separate and optional consent is required."}}, {"@type": "Question", "name": "Do I need cookie consent to use Google Analytics?", "acceptedAnswer": {"@type": "Answer", "text": "KVKK’s cookie guidelines may treat first-party analytics that only measures how the site works, with minimised data and no cross-site tracking, as falling under conditions other than explicit consent. Setups involving advertising features, remarketing or third-party tracking, however, require explicit consent."}}, {"@type": "Question", "name": "Does a cookie banner have to have a Reject button?", "acceptedAnswer": {"@type": "Answer", "text": "The Authority’s 2025 guidelines cite presenting the Accept, Reject and Preferences buttons in equal size, colour and font as good practice. Making rejecting as easy as accepting is the safest way to show that consent is based on free will."}}, {"@type": "Question", "name": "Can a KVKK privacy notice be copied from a template?", "acceptedAnswer": {"@type": "Answer", "text": "Not recommended. A privacy notice must describe what data you actually process, for what purpose and with which services. Copying another company’s text can lead to inaccurate and misleading information."}}]}</script>
